    },
    {
      "file": "emovec/vector_ops.py",
      "lines": "16-32",
      "severity": "low",
      "description": "A PCA variance threshold of 0 still returns one principal component, which is surprising for a public helper and config-controlled setting."
    },
    {
      "file": "outputs/tiny_demo/vectors/manifest.json",
